{
  "product": {
    "source_item_id": "1688986930661040",
    "source_1688_item_id": "986930661040",
    "title_es": "Guirnalda Navideña y Decoración de Fiesta para Fotografía",
    "description_es": "Añade un toque festivo a tus celebraciones con esta guirnalda decorativa. Ideal para fiestas de Navidad, cumpleaños o eventos temáticos. El diseño incluye letras 'Merry Christmas' o formas geométricas como copos de nieve y banderines triangulares. Fabricada con materiales ligeros y duraderos, es perfecta para colgar en paredes, techos o ventanas. Su estilo colorido crea un ambiente alegre y acogedor. Disponible en múltiples estilos visuales para adaptarse a tu temática específica. Úsala como fondo fotográfico o decoración principal.",
    "title_pt": "Guirlanda Natalina e Adereço para Festa e Fotos",
    "description_pt": "Decore suas festas com esta guirlanda temática perfeita para Natal e aniversários. O conjunto apresenta letras festivas ou formatos geométricos como estrelas e bandeirinhas triangulares. Material leve e resistente, ideal para pendurar em paredes, tetos ou janelas. Cria um ambiente alegre e convidativo para celebrações. Disponível em diversos modelos visuais para combinar com sua decoração. Excelente como fundo para fotos ou elemento central da festa. Fácil de instalar e remover, garantindo praticidade sem danificar superfícies.",
    "attributes": [
      {
        "name": "Style",
        "value_name": "Letter Banner / Triangle Flag"
      },
      {
        "name": "Occasion",
        "value_name": "Christmas / Birthday / Party"
      }
    ],
    "brand_terms": [],
    "product_type_en": "Party Decoration Banner"
  }
}

